"""CLI transfer messages; Studio passes its selected language via environment.
Standalone tools remain English unless TYPESTAR_STUDIO_LANGUAGE=fr.
"""
import os

MESSAGES = {'Type {mode} then Return on the Canon now.': 'Tapez {mode}, puis appuyez sur Return sur la Canon.', 'LOAD replaces the current program.': 'LOAD remplace le programme actuellement en mémoire.', 'Serial: {baud}/7{parity}{stopbits}. Set matching BAUD and SERCFG on Canon.': 'Liaison série : {baud}/7{parity}{stopbits}. Réglez BAUD et SERCFG de la même façon sur la Canon.', 'Program transfer acknowledged by the Canon.': 'Transfert du programme confirmé par la Canon.', 'Program saved to ': 'Programme enregistré dans ', 'Transfer failed: ': 'Échec du transfert : ', 'Destination already exists; choose a new filename': 'Le fichier de destination existe déjà ; choisissez un autre nom', 'Waiting for Canon ready': 'Attente de la Canon', 'Waiting for Canon LOAD-ready': 'Attente de la Canon pour LOAD', 'Waiting for Canon LOAD-ready (before sending program)': 'Attente de la Canon pour LOAD (avant envoi)', 'PC initial ACK': 'Acquittement initial du PC', 'PC final ACK': 'Acquittement final du PC', 'LOAD end': 'Fin de LOAD', 'LOAD end ACK': 'Acquittement de fin de LOAD', 'SAVE final ACK': 'Acquittement final de SAVE', 'SAVE line ACK': 'Acquittement de ligne SAVE', 'SAVE timeout': 'Délai de réception SAVE dépassé', 'Incomplete final line': 'Dernière ligne incomplète', 'Truncated/invalid native escape': 'Séquence de caractère natif tronquée ou invalide', 'Invalid/oversized SAVE line': 'Ligne SAVE invalide ou trop longue', 'Line exceeds 63 native bytes including its number': 'La ligne dépasse 63 octets natifs, numéro compris', 'LOAD record {index}': 'Enregistrement LOAD {index}', 'Transmit queue did not drain': 'La file d’émission ne s’est pas vidée', 'Short write: {written}/{size}': 'Écriture incomplète : {written}/{size}', 'handshake': 'Synchronisation', 'CTS={state}, pending TX={count} byte(s)': 'CTS={state}, {count} octet(s) en attente d’émission', 'READY': 'PRÊT', 'BLOCKED': 'BLOQUÉ', '{stage}: Canon RTS#/FTDI CTS remains BLOCKED; no bytes submitted. Check the LCD and CN7 pin 4 signal.': '{stage} : Canon RTS#/FTDI CTS reste BLOQUÉ ; aucun octet envoyé. Vérifiez le LCD et le signal de la broche 4 de CN7.', '{stage}: {detail}. {status}. Note the exact Canon LCD message. LOAD may be partial; no automatic retry.': '{stage} : {detail}. {status}. Relevez le message exact du LCD Canon. LOAD peut être partiel ; aucun nouvel essai automatique.', 'timeout (no byte received)': 'délai dépassé (aucun octet reçu)', 'unexpected byte 0x': 'octet inattendu 0x'}

def tr(text):
    return MESSAGES.get(text, text) if os.environ.get('TYPESTAR_STUDIO_LANGUAGE') == 'fr' else text
